const mobile=document.querySelector('#mobile-app'), web=document.querySelector('#web-app');
const state={mobile:'starter',web:'login',signedIn:false,record:'Local scan • Nov 4, 2026',planPreview:'free',role:'farmer',historyRange:'all'};
const assetBase=new URL('.',document.currentScript.src);
const logo=new URL('assets/icthyoscan-mark.svg',assetBase).href, fish=new URL('assets/bangus-scan-hero.png',assetBase).href;
const icon={home:'⌂',scan:'⌁',history:'◷',profile:'◉'};
function button(label,action,kind='primary'){return `<button class="${kind}" data-action="${action}">${label}</button>`}
function mHead(back=''){return `<header class="m-header"><div class="brand"><img src="${logo}" alt=""/>IcthyoScan</div>${back?`<button class="back-btn" data-mobile="${back}">←</button>`:''}</header>`}
function mNav(active){return `<nav class="m-nav">${[['dashboard','home','Home'],['capture','scan','Scan'],['history','history','History'],['profile','profile','Profile']].map(([screen,ic,label])=>`<button class="${active===screen?'active':''}" data-mobile="${screen}"><span class="nav-icon">${icon[ic]}</span>${label}</button>`).join('')}</nav>`}
function title(text,back){return `<div class="screen-title">${back?`<button class="back-btn" data-mobile="${back}">←</button>`:''}<h2>${text}</h2></div>`}
function mobileScreen(name){
 const aligned=alignedMobile(name);if(aligned)return aligned;
 const pages={
  starter:`<div class="m-page">${mHead()}<div class="m-main"><span class="eyebrow">Bangus farm companion</span><h1>See clearer. Care sooner.</h1><p class="muted">A private visual screening companion for routine Bangus health monitoring.</p><img class="hero-image" src="${fish}" alt="Bangus illustration"/><div class="welcome-card"><span class="chip">On-device screening</span><h3 style="margin-top:9px">Your farm data, close at hand.</h3><p class="muted">Images can be assessed on your device. Records will sync automatically when internet access returns.</p></div>${button('Get started','m:login','wide-button')}<p class="form-note" style="text-align:center">Preliminary visual screening only. It does not confirm vibriosis or replace professional assessment.</p></div></div>`,
  login:`<div class="m-page">${mHead('starter')}<div class="m-main">${title('Welcome back','starter')}<p class="muted">Sign in to view your farm monitoring records.</p><div class="form-field"><label>Email address</label><input value="farmer@example.com" aria-label="Email address"/></div><div class="form-field"><label>Password</label><input type="password" value="password" aria-label="Password"/></div>${button('Sign in','m:dashboard','wide-button')}<div class="divider">or</div>${button('Create a farmer account','m:register','secondary wide-button')}<p class="form-note">One Bangus farmer account can be used in the mobile app and supporting web dashboard.</p></div></div>`,
  register:`<div class="m-page">${mHead('login')}<div class="m-main">${title('Create your account','login')}<p class="muted">Start with a Free Plan. Core scanning and monitoring remain available while plan details are finalized.</p>${['Full name','Farm name','Email address','Password'].map(x=>`<div class="form-field"><label>${x}</label><input placeholder="${x}" aria-label="${x}"/></div>`).join('')}${button('Create account','m:dashboard','wide-button')}<p class="form-note">By continuing, you acknowledge that IcthyoScan provides preliminary visual screening only.</p></div></div>`,
  dashboard:`<div class="m-page">${mHead()}<div class="m-main"><span class="eyebrow">Good morning, Farmer</span><h1>Monitor your Bangus with confidence.</h1><div class="welcome-card"><div style="display:flex;justify-content:space-between;gap:10px"><div><span class="chip free">Free Plan</span><h3 style="margin-top:9px">Your core tools are ready.</h3></div><button class="text-link" data-mobile="plans">Plan info →</button></div><p class="muted">Capture or select a clear image to begin a preliminary screening.</p></div><div class="quick-grid"><button class="quick" data-mobile="sample"><span class="quick-icon">◌</span><b>Inspection sample</b><small>Optional population recommendation</small></button><button class="quick" data-mobile="capture"><span class="quick-icon">⌁</span><b>Capture or upload</b><small>Start a visual screening</small></button><button class="quick" data-mobile="guidance"><span class="quick-icon">✦</span><b>Care guidance</b><small>General biosecurity reminders</small></button><button class="quick" data-mobile="history"><span class="quick-icon">◷</span><b>Scan history</b><small>Local and synced records</small></button></div><div class="section-heading"><h3>Monitoring overview</h3></div><div class="stat-grid"><div class="stat"><strong>12</strong><span>Saved scans</span></div><div class="stat"><strong>3</strong><span>Pending sync</span></div></div></div>${mNav('dashboard')}</div>`,
  sample:`<div class="m-page">${mHead('dashboard')}<div class="m-main">${title('Inspection sample','dashboard')}<p class="muted">This optional guide helps organize visual inspection. It does not replace farm or veterinary procedures.</p><div class="form-field"><label>Estimated Bangus population</label><input type="number" placeholder="e.g., 500"/></div><div class="form-field"><label>Inspection context</label><select><option>Routine visual observation</option><option>Follow-up observation</option></select></div><div class="notice"><b>Recommendation preview</b><p class="muted">Enter your population estimate to view a demonstration recommendation. Final sampling rules require project approval.</p></div>${button('View recommendation','m:sample-result','wide-button')}</div>${mNav('dashboard')}</div>`,
  'sample-result':`<div class="m-page">${mHead('sample')}<div class="m-main">${title('Inspection guide','sample')}<div class="result-card"><span class="chip">Demonstration only</span><h2 style="margin-top:10px">Plan a representative visual check.</h2><p class="muted">Review Bangus from different pond areas and record only observations visible in the image. The project team will validate final sample-size rules.</p><div class="warning">No fixed sample-size threshold is shown because it has not yet been approved.</div></div>${button('Continue to capture','m:capture','wide-button')}</div>${mNav('dashboard')}</div>`,
  capture:`<div class="m-page">${mHead('dashboard')}<div class="m-main">${title('Capture Bangus image','dashboard')}<p class="muted">Use a clear image with good lighting and a visible fish body.</p><div class="quality-box"><div class="quality-icon">▣</div><h3>Camera preview</h3><p class="muted">Camera access is represented in this UI prototype.</p></div><div class="button-row" style="margin-top:12px">${button('Use camera','m:quality')}${button('Choose gallery','m:quality','secondary')}</div><div class="notice" style="margin-top:13px"><b>Image quality tips</b><p class="muted">Avoid motion blur, heavy reflections, and blocked or cropped body areas.</p></div></div>${mNav('capture')}</div>`,
  quality:`<div class="m-page">${mHead('capture')}<div class="m-main">${title('Image quality check','capture')}<div class="quality-box"><div class="quality-icon">✓</div><h3>Image is suitable to review</h3><p class="muted">The preview meets the demonstration quality checks for visibility and framing.</p></div><div class="card" style="margin-top:14px"><h3>On-device analysis</h3><p class="muted">YOLOv8n processing is represented as a UI state. Model inference is not included in this prototype.</p><div class="progress"><i style="width:72%"></i></div></div>${button('View preliminary result','m:result','wide-button')}</div>${mNav('capture')}</div>`,
  result:`<div class="m-page">${mHead('quality')}<div class="m-main">${title('Preliminary scan result','quality')}<span class="eyebrow">Screening advisory</span><h2 style="margin-top:6px">Visible observations need attention.</h2><div class="result-card"><div class="result-line"><b>Screening status</b><span class="result-badge">Review advised</span></div><div class="result-line"><span>Visible check</span><b>Skin area to observe</b></div><div class="result-line"><span>Image record</span><b>Saved locally</b></div></div><div class="warning" style="margin-top:12px">This is a preliminary visual screening advisory, not a confirmed vibriosis diagnosis. Consult qualified assistance for concerns.</div>${button('View care guidance','m:guidance','wide-button')}${button('Save & view history','m:history','secondary wide-button')}</div>${mNav('capture')}</div>`,
  guidance:`<div class="m-page">${mHead('dashboard')}<div class="m-main">${title('Care & biosecurity','dashboard')}<p class="muted">General, non-prescriptive reminders connected to the preliminary screening workflow.</p><div class="card"><h3>Observe and document</h3><ul class="guide-list"><li>Record clear images, dates, and pond observations.</li><li>Watch for changes in behavior or visible appearance.</li></ul></div><div class="card" style="margin-top:10px"><h3>Support good farm hygiene</h3><ul class="guide-list"><li>Follow your established cleaning and handling procedures.</li><li>Seek qualified guidance when observations persist or worsen.</li></ul></div><p class="form-note">IcthyoScan does not prescribe medication or confirm disease.</p></div>${mNav('dashboard')}</div>`,
  history:`<div class="m-page">${mHead('dashboard')}<div class="m-main">${title('Scan history','dashboard')}<p class="muted">Records save locally and synchronize automatically when connectivity returns.</p><div class="card">${record('Nov 4, 2026','Visible observation review advised','pending')}${record('Nov 2, 2026','No advisory shown','synced')}${record('Oct 28, 2026','Image needs recapture','review')}</div><div class="empty" style="margin-top:13px">There is no manual sync, edit, or delete action in the approved flow.</div></div>${mNav('history')}</div>`,
  details:`<div class="m-page">${mHead('history')}<div class="m-main">${title('Scan details','history')}<span class="tag pending">Pending automatic sync</span><h2 style="margin-top:12px">${state.record}</h2><div class="card"><div class="result-line"><span>Image source</span><b>Camera</b></div><div class="result-line"><span>Processing</span><b>On-device UI state</b></div><div class="result-line"><span>Record status</span><b>Stored locally</b></div></div><div class="notice" style="margin-top:12px"><b>Advisory</b><p class="muted">Use this record as a visual-observation reference. It does not establish a diagnosis.</p></div></div>${mNav('history')}</div>`,
  profile:`<div class="m-page">${mHead()}<div class="m-main"><div class="profile-head"><div class="avatar">FG</div><h2 style="margin-bottom:3px">Farmer Gigremosa</h2><p class="muted">bangusfarmer@example.com</p><span class="chip free">Free Plan</span></div><div class="plan-card"><span style="font-size:11px;font-weight:800">Your plan</span><h3 style="font-size:17px;margin:7px 0">Free Plan</h3><p>Core scanning and monitoring functions are available. Pro benefits and pricing are still subject to approval.</p><button class="secondary" data-mobile="plans">View plan information</button></div><div class="profile-row" data-mobile="edit"><span>✎</span><div><b>Edit profile</b><small>Update farmer and farm information</small></div><span class="right">›</span></div><div class="profile-row" data-mobile="plans"><span>◈</span><div><b>Subscription status</b><small>View approved plan information</small></div><span class="right">›</span></div><div class="profile-row" data-mobile="login"><span>⇥</span><div><b>Log out</b><small>Return to sign-in</small></div><span class="right">›</span></div></div>${mNav('profile')}</div>`,
  edit:`<div class="m-page">${mHead('profile')}<div class="m-main">${title('Edit profile','profile')}<div class="form-field"><label>Full name</label><input value="Farmer Gigremosa"/></div><div class="form-field"><label>Farm name</label><input value="Bangus Farm"/></div><div class="form-field"><label>Email address</label><input value="bangusfarmer@example.com"/></div>${button('Save changes','m:profile','wide-button')}</div>${mNav('profile')}</div>`,
  plans:`<div class="m-page">${mHead('profile')}<div class="m-main">${title('Plan information','profile')}<p class="muted">Plan presentation only. Billing and activation are not implemented.</p><div class="comparison"><div class="tier"><span class="chip free">Current</span><h3>Free</h3><ul><li>Approved core scan and monitoring tools</li><li>Account plan status</li><li>No fixed usage limits shown</li></ul></div><div class="tier featured"><span class="chip">Optional</span><h3>Pro</h3><ul><li>Upgrade presentation</li><li><span class="placeholder">Benefits pending approval</span></li><li><span class="placeholder">Price pending approval</span></li></ul></div></div><div class="notice" style="margin-top:14px"><b>Demonstration state</b><p class="muted">No payment provider, billing period, or successful activation is represented here.</p></div>${button('View Pro information','m:pro-status','wide-button')}</div>${mNav('profile')}</div>`,
  'pro-status':`<div class="m-page">${mHead('plans')}<div class="m-main">${title('Subscription status','plans')}<div class="plan-card"><span style="font-size:11px;font-weight:800">Demonstration state</span><h2 style="color:#fff;margin:7px 0">Pro Plan presentation</h2><p>This screen shows how a future activated plan could be displayed. No upgrade has been processed.</p></div><div class="notice"><b>Implementation note</b><p class="muted">Subscription activation, payment credentials, plan benefits, pricing, and billing periods require approval before implementation.</p></div>${button('Return to profile','m:profile','wide-button')}</div>${mNav('profile')}</div>`
 };
 return pages[name]||pages.starter;
}
function record(date,text,status){return `<div class="record" data-mobile="details"><div class="fish-dot">🐟</div><div><b>${text}</b><small>${date} · Camera image</small></div><span class="right tag ${status}">${status==='pending'?'Pending sync':status==='synced'?'Synced':'Recapture'}</span></div>`}
function webShell(content,active='dashboard'){return `<header class="web-header"><div class="web-brand"><img src="${logo}" alt=""/>IcthyoScan</div><nav class="web-nav">${[['dashboard','Dashboard'],['web-history','Scan history'],['web-profile','Profile'],['web-plans','Plan info']].map(([id,label])=>`<button class="${active===id?'active':''}" data-web="${id}">${label}</button>`).join('')}</nav><div class="web-user"><div class="web-avatar">FG</div>Farmer</div></header>${content}`}
function webScreen(name){
 const aligned=alignedWeb(name);if(aligned)return aligned;
 const pages={
 login:`<div class="web-login"><div class="web-login-card"><div class="web-brand"><img src="${logo}" alt=""/>IcthyoScan</div><img class="web-hero-fish" src="${fish}" alt="Bangus illustration"/><h1>Welcome back</h1><p class="muted">View your synchronized Bangus monitoring records.</p><div class="form-field"><label>Email address</label><input value="farmer@example.com"/></div><div class="form-field"><label>Password</label><input type="password" value="password"/></div>${button('Sign in to dashboard','w:dashboard','wide-button')}<p class="form-note">The web dashboard does not capture images or run AI analysis.</p></div></div>`,
 dashboard:webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Online monitoring</span><h1>Farm health overview</h1><p>Review synchronized visual-screening records from your farmer account.</p></div><button class="ghost-button" data-web="web-history">View all records</button></div><div class="web-banner"><b>Sync status:</b> 3 records are represented as awaiting automatic synchronization. Manual synchronization is not part of this interface.</div><div class="web-stats"><div class="web-stat"><span>Synchronized scans</span><b>9</b></div><div class="web-stat"><span>Pending automatic sync</span><b>3</b></div><div class="web-stat"><span>Review advisories</span><b>2</b></div><div class="web-stat"><span>Current plan</span><b style="font-size:17px;margin-top:12px">Free</b></div></div><div class="web-grid"><section class="web-card"><h2>Record activity</h2><p>Demonstration visualization of synchronized records, not disease mapping.</p><div class="chart">${[48,72,38,91,64,52,78].map((n,i)=>`<div class="bar" style="height:${n}%"><span>${['M','T','W','T','F','S','S'][i]}</span></div>`).join('')}</div></section><section class="web-card"><h2>Quick information</h2><p>Use the Android application to capture or select Bangus images for preliminary on-device screening.</p><div class="notice"><b>Scope reminder</b><p class="muted">The dashboard presents records only; it does not run web-based AI screening.</p></div><button class="ghost-button" data-web="web-plans">View plan information</button></section></div></main>`,'dashboard'),
 'web-history':webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Synchronized records</span><h1>Scan history</h1><p>Online records received from the farmer's mobile app.</p></div></div><section class="web-card table-wrap"><table class="web-table"><thead><tr><th>Date</th><th>Record</th><th>Advisory</th><th>Status</th></tr></thead><tbody><tr data-web="web-details"><td>Nov 2, 2026</td><td>Bangus visual observation</td><td>Review advised</td><td><span class="tag synced">Synced</span></td></tr><tr data-web="web-details"><td>Oct 28, 2026</td><td>Bangus visual observation</td><td>No advisory shown</td><td><span class="tag synced">Synced</span></td></tr><tr data-web="web-details"><td>Oct 20, 2026</td><td>Bangus visual observation</td><td>Image needs recapture</td><td><span class="tag synced">Synced</span></td></tr></tbody></table></section></main>`,'web-history'),
 'web-details':webShell(`<main class="web-main"><div class="web-title"><div><button class="back-btn" data-web="web-history">← Back to history</button><h1 style="margin-top:12px">Individual scan record</h1><p>Synchronized mobile record · Nov 2, 2026</p></div></div><div class="split-card"><section class="web-card"><h2>Preliminary screening advisory</h2><div class="warning">Review advised — this record is not a confirmed vibriosis diagnosis.</div><div class="result-line" style="margin-top:13px"><span>Source</span><b>Android camera</b></div><div class="result-line"><span>Processing location</span><b>On-device</b></div><div class="result-line"><span>Sync state</span><b>Received online</b></div></section><section class="web-card"><h2>General care reference</h2><p>Follow your established farm hygiene and observation procedures. Seek qualified guidance if concerns persist.</p><button class="ghost-button" data-web="web-history">Return to history</button></section></div></main>`,'web-history'),
 'web-profile':webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Farmer account</span><h1>Profile</h1><p>Shared account details for Android and web.</p></div><button class="ghost-button" data-web="web-edit">Edit profile</button></div><div class="split-card"><section class="web-card"><div class="profile-head"><div class="avatar">FG</div><h2>Farmer Gigremosa</h2><p>bangusfarmer@example.com</p><span class="chip free">Free Plan</span></div></section><section class="web-card"><h2>Account plan</h2><p>Your approved core monitoring functions remain available. Pro plan benefits, pricing, and billing details are intentionally not shown until approved.</p><button class="ghost-button" data-web="web-plans">View plan information</button></section></div></main>`,'web-profile'),
 'web-edit':webShell(`<main class="web-main"><div class="web-form"><button class="back-btn" data-web="web-profile">← Back to profile</button><h1 style="margin-top:16px">Edit profile</h1><div class="web-card"><div class="form-field"><label>Full name</label><input value="Farmer Gigremosa"/></div><div class="form-field"><label>Farm name</label><input value="Bangus Farm"/></div><div class="form-field"><label>Email address</label><input value="bangusfarmer@example.com"/></div>${button('Save changes','w:web-profile','wide-button')}</div></div></main>`,'web-profile'),
 'web-plans':webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Account plan</span><h1>Plan information</h1><p>Presentation of approved plan states; no transaction or activation occurs here.</p></div></div><div class="split-card"><section class="web-card"><span class="chip free">Current plan</span><h2 style="margin-top:10px">Free</h2><p>Default state for newly registered farmers. The approved core Bangus screening and monitoring functions remain accessible.</p><ul class="guide-list"><li>Core functions are not limited in this prototype.</li><li>Plan status is visible on the account screens.</li></ul></section><section class="web-card" style="border-color:#76c9c2"><span class="chip">Optional upgrade</span><h2 style="margin-top:10px">Pro</h2><p>A separate plan presentation for a future approved upgrade.</p><p><span class="placeholder">Benefits pending approval</span> <span class="placeholder">Price pending approval</span> <span class="placeholder">Billing period pending approval</span></p><div class="notice"><b>Demonstration only</b><p class="muted">No payment provider or successful activation is represented.</p></div></section></div></main>`,'web-plans')
 };
 return pages[name]||pages.login;
}
const gallery=document.querySelector('#gallery-app');
const screens=[
 ['android','starter','A01','Starter Screen'],['android','login','A02','Login Screen'],['android','register','A03','Registration Screen'],['android','dashboard','A04','Mobile Dashboard'],['android','sample','A05','Inspection Sample Size Recommendation'],['android','capture','A06','Capture or Upload Bangus Image'],['android','quality','A07','Image Quality Validation & AI Analysis'],['android','result','A08','Preliminary Scan Result'],['android','guidance','A09','Care & Biosecurity Guidance'],['android','history','A10','Scan History'],['android','details','A11','Scan Details'],['android','profile','A12','Profile'],['android','edit','A13','Edit Profile'],['subscription','plans','S01','Subscription / Plan Comparison'],['subscription','pro-status','S02','Subscription Status'],
 ['web','login','W01','Web Login'],['web','dashboard','W02','Online Monitoring Dashboard'],['web','web-history','W03','Synchronized Scan History'],['web','web-details','W04','Individual Scan Details'],['web','web-profile','W05','Web Profile'],['web','web-edit','W06','Web Edit Profile'],['web','web-plans','W07','Web Subscription / Plan Comparison']
].map(([platform,key,id,name])=>({platform,key,id,name,path:platform==='subscription'?(key==='plans'?'/prototype/subscription':'/prototype/subscription/status'):`/prototype/${platform}/${key}`}));
let selected=screens[0],phoneFrame=true;
screens.forEach((screen,index)=>{screen.figure=index+6;if(screen.key==='plans')screen.name='Plan Information';if(screen.key==='pro-status')screen.name='Subscription Status';if(screen.key==='web-history')screen.name='Web Scan History';if(screen.key==='web-details')screen.name='Web Scan Details';if(screen.key==='web-plans')screen.name='Web Plan Information';});
function routeURL(){return new URL(location.hash.startsWith('#/')?location.hash.slice(1):location.pathname+location.search,'https://gallery.local');}
function go(path){if(location.protocol==='file:'){location.hash=path;}else{history.pushState({},'',path);renderGallery();}}
function fromLocation(){const route=routeURL(),path=route.pathname.replace(/\/$/,'')||'/';const screenshot=path==='/prototype/screenshots';const requested=screenshot?route.searchParams.get('screen'):null;const match=screenshot&&requested?screens.find(x=>`${x.platform}/${x.key}`===requested):screens.find(x=>x.path===path);if(match)selected=match;if(route.searchParams.has('record'))state.recordId=route.searchParams.get('record');if(route.searchParams.has('role'))state.role=route.searchParams.get('role')==='owner'?'owner':'farmer';if(route.searchParams.has('quality'))state.qualityRejected=route.searchParams.get('quality')==='rejected';if(route.searchParams.has('plan'))state.planPreview=route.searchParams.get('plan')==='pro'?'pro':'free';phoneFrame=route.searchParams.get('frame')!=='off';return {screenshot:screenshot&&!!match,overview:!match&&!screenshot||path==='/prototype/gallery'||path==='/'}}
function previewMarkup(item,clean=false){const body=item.platform==='web'?webScreen(item.key):mobileScreen(item.key);if(item.platform==='web')return `<div class="web-canvas ${clean?'clean-canvas':''}">${body}</div>`;return `<div class="phone ${phoneFrame?'':'no-frame'}"><div class="phone-speaker"></div><div class="phone-screen">${body}</div></div>`}
function sideGroup(label,platform){return `<section class="screen-group"><h2>${label}</h2>${screens.filter(x=>x.platform===platform).map(x=>`<button class="screen-link ${x===selected?'active':''}" data-screen="${x.platform}/${x.key}"><span class="screen-number">${x.id}</span><b>${x.name}</b></button>`).join('')}</section>`}
function overviewCard(x){return `<article class="screen-card ${x.platform==='web'?'desktop-card':''}"><div class="screen-card-heading"><div><small>${x.id} · ${x.platform==='web'?'Web dashboard':'Android preview'}</small><h3>${x.name}</h3></div></div><div class="screen-card-actions"><button class="tool-btn" data-screen="${x.platform}/${x.key}">Open screen</button><button class="tool-btn primary-tool" data-capture="${x.platform}/${x.key}">Screenshot view ↗</button></div><div class="screen-card-preview" inert>${previewMarkup(x)}</div></article>`;}
function overview(){phoneFrame=true;return `<div class="gallery-overview"><header class="catalogue-hero"><div class="catalogue-brand"><img src="${logo}" alt="IcthyoScan logo"/><div><b>IcthyoScan</b><p>Bangus health monitoring</p></div></div><div><span class="eyebrow">Mobile and web prototype gallery</span><h1>IcthyoScan Interface Designs</h1><p>Browse every interface, open an interactive preview, or isolate a screen for your Chapter III manuscript.</p><p class="catalogue-note">Browser representations of the proposed interfaces · Sample data · Preliminary visual screening</p></div></header><nav class="catalogue-jump"><a href="#android-section">Android application · 13</a><a href="#subscription-section">Free / Pro · 2</a><a href="#web-section">Web dashboard · 7</a></nav>${[['android','Android Application','Phone-sized previews for Bangus farmers.'],['subscription','Free and Pro Interfaces','Proposed account-plan screens with unapproved details clearly marked.'],['web','Web Dashboard','Desktop previews for viewing synchronized monitoring records.']].map(([platform,label,description])=>`<section id="${platform}-section" class="catalogue-section"><span class="eyebrow">${screens.filter(x=>x.platform===platform).length} screens</span><h2>${label}</h2><p>${description}</p><div class="real-screen-grid ${platform==='web'?'web-screen-grid':''}">${screens.filter(x=>x.platform===platform).map(overviewCard).join('')}</div></section>`).join('')}</div>`}
function galleryView(){const i=screens.indexOf(selected),prev=screens[i-1],next=screens[i+1];return `<div class="gallery"><aside class="gallery-sidebar"><div class="gallery-brand"><img src="${logo}" alt=""/>IcthyoScan</div><p class="gallery-subtitle">Mobile Edge-AI Vision System for preliminary Bangus health screening.</p><button class="side-overview" data-gallery="overview">All screens · ${screens.length}</button>${sideGroup('Android application','android')}${sideGroup('Subscription interfaces','subscription')}${sideGroup('Web dashboard','web')}</aside><section class="gallery-main"><header class="gallery-toolbar"><div class="breadcrumb"><span>${selected.id} · ${selected.platform==='android'?'Android application':selected.platform==='web'?'Web dashboard':'Subscription interface'}</span><h1>${selected.name}</h1></div>${selected.platform!=='web'?`<button class="tool-btn" data-frame>${phoneFrame?'Hide phone frame':'Show phone frame'}</button>`:''}<button class="tool-btn" data-fullscreen>Fullscreen</button><button class="tool-btn primary-tool" data-screenshot>Screenshot mode</button></header><main class="gallery-preview"><div class="preview-meta"><span>Interactive prototype · Sample data only</span><span>${i+1} of ${screens.length}</span></div><div class="preview-stage">${previewMarkup(selected)}</div><nav class="preview-navigation"><button ${!prev?'disabled':''} ${prev?`data-screen="${prev.platform}/${prev.key}"`:''}>← Previous</button><button data-gallery="overview">Gallery overview</button><button ${!next?'disabled':''} ${next?`data-screen="${next.platform}/${next.key}"`:''}>Next →</button></nav></main></section></div>`}
function fitPreviews(){document.querySelectorAll('.screen-card-preview,.preview-stage').forEach(host=>{const canvas=host.firstElementChild;if(!canvas)return;const width=canvas.classList.contains('web-canvas')?1440:370;canvas.style.zoom=String(Math.min(1,host.clientWidth/width));});}
function renderGallery(){const mode=fromLocation();document.body.classList.toggle('capture-mode',mode.screenshot);if(mode.screenshot){gallery.innerHTML=`<main class="screenshot-page">${previewMarkup(selected,true)}</main>`;return}gallery.innerHTML=mode.overview?overview():galleryView();requestAnimationFrame(fitPreviews);}
function navigate(item){selected=item;state.mobile=item.platform==='web'?state.mobile:item.key;state.web=item.platform==='web'?item.key:state.web;go(item.path+(['details','web-details'].includes(item.key)?`?record=${state.recordId||'IS-1102'}`:''));}
function render(){renderGallery()}
document.addEventListener('click',e=>{
 const target=e.target.closest('button,a,[data-mobile],[data-web]');if(!target)return;
 if(target.dataset.role){state.role=target.dataset.role==='owner'?'owner':'farmer';const route=routeURL();route.searchParams.set('role',state.role);go(route.pathname+route.search);return;}
 if(target.dataset.record){state.recordId=target.dataset.record;const item=screens.find(x=>x.key===(target.dataset.recordPlatform==='web'?'web-details':'details'));navigate(item);return;}
 if(target.dataset.source){state.imageSource=target.dataset.source;demoRecords[0].source=target.dataset.source;state.qualityRejected=false;navigate(screens.find(x=>x.key==='quality'));return;}
 if(target.dataset.quality){state.qualityRejected=target.dataset.quality==='rejected';renderGallery();return;}
 if(target.dataset.planPreview){state.planPreview=target.dataset.planPreview==='pro'?'pro':'free';state.historyRange='all';const route=routeURL();route.searchParams.set('plan',state.planPreview);go(route.pathname+route.search);return;}
 if(target.dataset.historyRange){state.historyRange=target.dataset.historyRange;renderGallery();return;}
 if(target.dataset.saveProfile){const name=document.querySelector('[data-profile-name]')?.value.trim(),email=document.querySelector('[data-profile-email]')?.value.trim();if(name)acct().name=name;if(email)acct().email=email;navigate(screens.find(x=>x.key===(target.dataset.saveProfile==='web'?'web-profile':'profile')));return;}
 if(target.matches('[data-screen]')){const item=screens.find(x=>`${x.platform}/${x.key}`===target.dataset.screen);if(item)navigate(item);return;}
 if(target.matches('[data-gallery]')){go('/prototype/gallery');return;}
 if(target.matches('[data-frame]')){const route=routeURL();route.searchParams.set('frame',phoneFrame?'off':'on');go(route.pathname+route.search);return;}
 if(target.matches('[data-fullscreen]')){document.querySelector('.preview-stage')?.requestFullscreen?.();return;}
 if(target.matches('[data-screenshot],[data-capture]')){const screen=target.dataset.capture||`${selected.platform}/${selected.key}`;const path=`/prototype/screenshots?screen=${encodeURIComponent(screen)}&frame=${phoneFrame?'on':'off'}&record=${state.recordId||'IS-1102'}&plan=${state.planPreview||'free'}&quality=${state.qualityRejected?'rejected':'accepted'}&role=${state.role||'farmer'}`;const url=new URL(location.href);if(location.protocol==='file:'){url.hash=path;}else{url.pathname='/prototype/screenshots';url.search=path.split('?')[1];url.hash='';}window.open(url.href,'_blank','noopener');return;}
 const platform=target.matches('[data-web]')?'web':target.matches('[data-action]')?(target.dataset.action.startsWith('w:')?'web':'android'):'android';
 const key=target.dataset.mobile||target.dataset.web||target.dataset.action?.split(':')[1];
 const item=screens.find(x=>(platform==='web'?x.platform==='web':x.platform!=='web')&&x.key===key);if(item)navigate(item);
});
window.addEventListener('popstate',renderGallery);
window.addEventListener('resize',fitPreviews);
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))renderGallery();});
render();
